  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'أكمل كل تكرار في كل مجموعة ويرتفع الوزن. الإخفاق المتكرر يؤدي إلى تخفيف الحمل.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up — double if you double the reps. One failure resets 10 %.': 'مجموعتان عاديتان ثم مجموعة أخيرة حتى الإخفاق. تجاوز الهدف فيها ويرتفع الوزن — ضعفين إن ضاعفت التكرارات. إخفاق واحد يعيد 10 %.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'اصعد عبر نطاق تكرارات بالوزن نفسه. ابلغ أعلى النطاق في كل مجموعة ويرتفع الوزن، وتعود التكرارات إلى الأدنى.',
  'Hold every set for the full duration and the target goes up.': 'اثبت في كل مجموعة طوال المدة ويرتفع الهدف.',
