  'Short {0} sessions in a row — back off to {1}s and build up again.': 'قصّرت {0} جلسات متتالية — تراجع إلى {1} ث وابنِ من جديد.',
  'Last time came up short — same target again.': 'المرة الماضية لم تكتمل — الهدف نفسه مجددًا.',
  'Top of the rep range in every set — {0} {1} more, back to {2} reps.': 'أعلى نطاق التكرارات في كل مجموعة — {0} {1} إضافية، والعودة إلى {2} تكرارات.',
  'Stalled {0} sessions — deload to {1} {2}.': 'توقّف التقدّم {0} جلسات — خفّف إلى {1} {2}.',
  'Same weight — aim for {0} reps this time.': 'الوزن نفسه — استهدف {0} تكرارات هذه المرة.',
  'Last set hit {0} reps — twice the target, so take a double jump of {1} {2}.': 'آخر مجموعة بلغت {0} تكرارات — ضعف الهدف، فاقفز قفزة مزدوجة بمقدار {1} {2}.',
