  'RIR counts the reps you left; RPE reads the same effort off a 10-point scale — so RPE ≈ 10 − RIR. Pick the one you already think in.': '«المتبقّي» يعدّ التكرارات التي كان بإمكانك أداؤها بعد؛ و«الجهد» يقرأ الجهد نفسه على مقياس من 10 — أي الجهد ≈ 10 − المتبقّي. اختر ما تفكّر به أصلًا.',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value — progression and estimated 1RM are unaffected.': 'الصف المظلّل هو حيث تقع معظم مجموعات العمل. المجموعات المسجّلة سابقًا تحتفظ بمقياسها، ولا شيء آخر يقرأ القيمة — التدرّج وأقصى وزن تقديري لا يتأثران.',
