  'Week by week': 'أسبوعًا بأسبوع',
  'Where the sets land': 'أين تقع المجموعات',
  'Most working sets belong close to failure without living there — half at the floor and half at the top average out to a healthy-looking middle.': 'معظم مجموعات العمل مكانها قرب الإخفاق دون البقاء فيه — نصف عند الحد الأدنى ونصف عند الأعلى يعطيان متوسطًا يبدو صحيًا.',
  'Average effort per workout': 'متوسط الجهد لكل تمرين',
  'A fuller dot means less left in the tank — the same weight at a lower {0} is progress the line alone does not show.': 'النقطة الأكثر امتلاءً تعني أن ما تبقّى في الخزان أقل — الوزن نفسه عند {0} أقل تقدّم لا يُظهره الخط وحده.',
