  'An AI coach that can build your plan and adjust it from what you log. Off until you turn it on.': 'مدرّب ذكي يمكنه بناء خطتك وتعديلها بناءً على ما تسجّله. متوقف حتى تفعّله.',
  'An AI coach that can design your plan and adjust it from what you actually log. It runs on this server, it never changes anything without your say-so, and it is off until you turn it on.': 'مدرّب ذكي يمكنه تصميم خطتك وتعديلها بناءً على ما تسجّله فعلًا. يعمل على هذا الخادم، ولا يغيّر شيئًا دون موافقتك، ويبقى متوقفًا حتى تفعّله.',
  'Any pending suggestion is discarded and scheduled reviews stop. Your Coach history stays, and you can turn it back on anytime.': 'يُتجاهل أي اقتراح معلّق وتتوقف المراجعات المجدولة. يبقى سجل المدرّب، ويمكنك إعادة تفعيله متى شئت.',
