  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'إصابات، مفاصل تشتكي، حركات لا تستطيع أداءها، أو قيود عملية مثل التمرين السادسة صباحًا في شقة.',
