  'Only while today’s step goal isn’t met yet.': 'فقط ما دام هدف الخطوات اليوم لم يتحقق.',
  'Reminds you at this time on days that have a routine planned and not yet trained — with your step goal in the same notification.': 'يذكّرك في هذا الوقت في الأيام التي فيها روتين مخطّط لم تتمرّنه بعد — مع هدف خطواتك في الإشعار نفسه.',
  'Counting with your phone’s step sensor.': 'العدّ بحسّاس الخطوات في هاتفك.',
  'Counting with the motion sensor — keep MAHDI-JYM open and on screen.': 'العدّ بحسّاس الحركة — أبقِ MAHDI-JYM مفتوحًا وظاهرًا على الشاشة.',
  'Starting…': 'جارٍ البدء…',
  'Paused — your steps so far are kept.': 'متوقف مؤقتًا — خطواتك حتى الآن محفوظة.',
  'Motion access was denied. Allow it in your system settings, then try again.': 'تم رفض الوصول إلى الحركة. اسمح به في إعدادات النظام ثم حاول مجددًا.',
  'This device has no step sensor or accelerometer we can read.': 'لا يحتوي هذا الجهاز على حسّاس خطوات أو مقياس تسارع يمكننا قراءته.',
  'The step counter could not start. Try again.': 'تعذّر تشغيل عدّاد الخطوات. حاول مجددًا.',
  'Uses your phone’s built-in step sensor — light on battery.': 'يستخدم حسّاس الخطوات المدمج في هاتفك — خفيف على البطارية.',
  'Counts steps with your phone’s motion sensor while this page is open.': 'يعدّ الخطوات بحسّاس الحركة في هاتفك ما دامت هذه الصفحة مفتوحة.',
  'Walking': 'المشي',
