  'Best day: {0} steps on {1}': 'أفضل يوم: {0} خطوة في {1}',
  'Goal & counter': 'الهدف والعدّاد',
  'Android keeps counting in its step sensor while the app sleeps; the steps arrive the next time MAHDI-JYM reads it. On iPhone, today’s total is filled in from the motion history.': 'يواصل أندرويد العدّ في حسّاس الخطوات أثناء نوم التطبيق؛ وتصل الخطوات في المرة التالية التي يقرأه فيها MAHDI-JYM. على آيفون، يُكمَّل إجمالي اليوم من سجل الحركة.',
  'Browsers only deliver motion data while the page is open and on screen. For all-day counting, install the Android app.': 'لا تقدّم المتصفحات بيانات الحركة إلا والصفحة مفتوحة وظاهرة على الشاشة. للعدّ طوال اليوم، ثبّت تطبيق أندرويد.',
  'Stride length': 'طول الخطوة',
  'Estimated: {0} cm': 'تقديري: {0} سم',
  'Step notification': 'إشعار الخطوات',
  'Stays in your notifications while counting, updated as you walk.': 'يبقى في إشعاراتك أثناء العدّ ويتحدّث وأنت تمشي.',
  'Vibrate every 1,000 steps': 'اهتزاز كل 1000 خطوة',
  'Celebrations': 'الاحتفالات',
