  'Your steps today, updated as you walk — also on the lock screen.': 'خطواتك اليوم، تتحدّث أثناء المشي — حتى على شاشة القفل.',
  'Every 1,000 steps and your daily goal, with a sound.': 'كل 1000 خطوة وعند بلوغ هدفك اليومي، مع صوت.',
