  // 2.8 — Google account without setup (Android Backup)
  'Welcome back — your data was restored from your Google account': 'أهلًا بعودتك — استُعيدت بياناتك من حساب Google',
  'Google Drive isn’t set up for this version of the app yet — your data is still saved to your Google account through Android Backup.': 'لم يُعَدّ Google Drive لهذه النسخة من التطبيق بعد — ومع ذلك تُحفظ بياناتك في حساب Google عبر النسخ الاحتياطي لأندرويد.',
  'Saved privately to your Google account — only MAHDI-JYM can read it. Sign out anytime in Settings.': 'تُحفظ بخصوصية في حساب Google — لا يقرؤها إلا MAHDI-JYM. يمكنك تسجيل الخروج متى شئت من الإعدادات.',
  'Everything is saved to your Google account automatically through Android Backup, and comes back when you install MAHDI-JYM again.': 'يُحفظ كل شيء في حساب Google تلقائيًا عبر النسخ الاحتياطي لأندرويد، ويعود عند تثبيت MAHDI-JYM من جديد.',
  'Now saved to Google Drive': 'أصبح الحفظ الآن في Google Drive',
  'Your data stays on this phone. Changes are no longer saved to your Google account.': 'تبقى بياناتك على هذا الهاتف، ولن تُحفظ التغييرات بعد الآن في حساب Google.',
  'Sign in with a Google account that’s already on this phone — no password. Everything is then saved to that account automatically.': 'سجّل الدخول بحساب Google موجود على هذا الهاتف — بلا كلمة مرور. بعدها يُحفظ كل شيء في ذلك الحساب تلقائيًا.',
  'Workouts, plan, steps, water, body weight and settings are saved through Android Backup to your Google account. Android uploads it in the background, usually within a few hours, and puts it back when you install MAHDI-JYM again or on a new phone. Progress photos stay on this phone.': 'تُحفظ التمارين والخطة والخطوات والماء ووزن الجسم والإعدادات في حساب Google عبر النسخ الاحتياطي لأندرويد. يرفعها أندرويد في الخلفية، عادةً خلال بضع ساعات، ويعيدها عند تثبيت MAHDI-JYM من جديد أو على هاتف جديد. تبقى صور التقدّم على هذا الهاتف.',
  'Google Drive': 'Google Drive',
  'Android Backup': 'النسخ الاحتياطي لأندرويد',
  'Private app folder · synced within seconds': 'مجلد تطبيق خاص · مزامنة خلال ثوانٍ',
  'Through your Google account · no setup needed': 'عبر حساب Google · دون أي إعداد',
  'Use Google Drive': 'استخدام Google Drive',
  'Needs the one-time Google Cloud setup — tried automatically every few hours': 'يحتاج إلى إعداد Google Cloud لمرة واحدة — تُعاد المحاولة تلقائيًا كل بضع ساعات',
  'Faster sync between phones': 'مزامنة أسرع بين الهواتف',
