  "That needs a one-time setup in Google Cloud by the app’s owner. Until then everything is saved through Android Backup — nothing is lost.": "يحتاج ذلك إلى إعداد لمرة واحدة في Google Cloud من مالك التطبيق. وحتى ذلك الحين يُحفظ كل شيء عبر النسخ الاحتياطي لأندرويد — لا يضيع شيء.",
