  "Automatic versions": "النسخ التلقائية",
  "Once a day, when something changed, a full copy is kept on this phone and in Google Drive. The newest ones are kept; older ones are removed.": "مرة يوميًا، عند حدوث أي تغيير، تُحفظ نسخة كاملة على هذا الهاتف وفي Google Drive. تُبقى الأحدث وتُحذف الأقدم.",
  "Once a day, when something changed, a full copy is kept on this phone. The newest ones are kept; older ones are removed.": "مرة يوميًا، عند حدوث أي تغيير، تُحفظ نسخة كاملة على هذا الهاتف. تُبقى الأحدث وتُحذف الأقدم.",
