  "On this phone": "على هذا الهاتف",
  "No versions yet — the first one is saved today.": "لا توجد نسخ بعد — تُحفظ أول نسخة اليوم.",
  "In Google Drive": "في Google Drive",
  "Refresh": "تحديث",
  "Loading…": "جارٍ التحميل…",
  "Could not reach Google Drive — check the connection.": "تعذّر الوصول إلى Google Drive — تحقّق من الاتصال.",
  "No versions in Drive yet.": "لا توجد نسخ في Drive بعد.",
  "A version is a full copy: workouts, plan, routines, steps, water, body weight, health log and settings. Progress photos stay where they are. For a copy you can keep anywhere, use Export in Settings.": "النسخة نسخة كاملة: التمارين والخطة والروتينات والخطوات والماء ووزن الجسم والسجل الصحي والإعدادات. أما صور التقدّم فتبقى في مكانها. وللحصول على نسخة تحفظها في أي مكان، استخدم التصدير في الإعدادات.",
  "Open console.cloud.google.com with your Google account and create a project (any name).": "افتح console.cloud.google.com بحساب Google الخاص بك وأنشئ مشروعًا (بأي اسم).",
  "APIs & Services → Library → search “Google Drive API” → Enable.": "APIs & Services ← Library ← ابحث عن «Google Drive API» ← Enable.",
  "OAuth consent screen → External → fill in the app name and your email → add the scope …/auth/drive.appdata → add your own account as a test user.": "OAuth consent screen ← External ← اكتب اسم التطبيق وبريدك ← أضف النطاق ‎…/auth/drive.appdata ← أضف حسابك كمستخدم تجريبي (test user).",
  "Credentials → Create credentials → OAuth client ID → Android → paste the package name and SHA-1 below.": "Credentials ← Create credentials ← OAuth client ID ← Android ← الصق اسم الحزمة وبصمة SHA-1 الموجودين في الأسفل.",
  "Wait about 5 minutes, then come back here and tap Try again. Nothing changes in the app itself.": "انتظر نحو 5 دقائق، ثم ارجع هنا واضغط «حاول مجددًا». لا يتغيّر شيء في التطبيق نفسه.",
  "Switch on Google Drive": "تفعيل Google Drive",
  "Only needed once, by the app’s owner. Saving through Android Backup keeps working the whole time.": "يلزم مرة واحدة فقط ومن مالك التطبيق. ويستمر الحفظ عبر النسخ الاحتياطي لأندرويد طوال الوقت.",
  "Package name": "اسم الحزمة",
  "Full guide: docs/GOOGLE_SIGN_IN.md in the project.": "الدليل الكامل: الملف docs/GOOGLE_SIGN_IN.md في المشروع.",
