  // 4.1 — Google check, today’s workout linked to the scale
  "The Google Drive API is switched off in the Cloud project": "واجهة Google Drive API مُعطّلة في مشروع Google Cloud",
  "In Google Cloud: APIs & Services → Library → Google Drive API → Enable. Then test again in a few minutes.": "في Google Cloud: ‏APIs & Services ← Library ← Google Drive API ← Enable. ثم اختبر مجددًا بعد بضع دقائق.",
  "Google doesn’t know this app yet": "Google لا يعرف هذا التطبيق بعد",
  "Create an Android OAuth client in Google Cloud with exactly the package name and SHA-1 shown here. Wait about 5 minutes, then test again.": "أنشئ عميل OAuth من نوع Android في Google Cloud باسم الحزمة وبصمة SHA-1 الظاهرين هنا تمامًا. انتظر نحو 5 دقائق ثم اختبر مجددًا.",
  "Access to Google Drive wasn’t allowed": "لم يُسمح بالوصول إلى Google Drive",
  "Tap Test Google Drive and choose Allow. While the app is in testing, your account must be listed as a test user on the OAuth consent screen.": "اضغط «اختبار Google Drive» واختر «السماح». ما دام التطبيق في وضع الاختبار يجب أن يكون حسابك مُضافًا كمستخدم اختبار في شاشة موافقة OAuth.",
  "Google refused access for this account": "رفض Google الوصول لهذا الحساب",
  "On the OAuth consent screen: user type External, your account added as a test user, and the scope …/auth/drive.appdata added. Then test again.": "في شاشة موافقة OAuth: نوع المستخدم External، وحسابك مُضاف كمستخدم اختبار، والنطاق ‎…/auth/drive.appdata مُضاف. ثم اختبر مجددًا.",
  "No connection to Google": "لا يوجد اتصال بـ Google",
  "Check the internet connection and try again.": "تحقّق من اتصال الإنترنت وحاول مجددًا.",
  "Not signed in": "لم يتم تسجيل الدخول",
  "Sign in with your Google account in Settings.": "سجّل الدخول بحساب Google من الإعدادات.",
  "Update Google Play services from the Play Store, then try again.": "حدّث خدمات Google Play من متجر Play ثم حاول مجددًا.",
  "Google Drive answered with an error": "ردّ Google Drive بخطأ",
  "Try again later. If it keeps happening, the code below tells what Google said.": "حاول لاحقًا. إن تكرّر ذلك فالرمز أدناه يوضّح ما قاله Google.",
  "Weigh yourself to get a workout matched to your scale.": "سجّل وزنك لتحصل على تمرين مطابق لميزانك.",
  "You are {0} kg above your ideal weight — today is built to burn more calories.": "وزنك أعلى من وزنك المثالي بـ {0} كغ — تمرين اليوم مُصمَّم لحرق سعرات أكثر.",
  "You are {0} kg above your target weight — today is built to burn more calories.": "وزنك أعلى من وزنك المستهدف بـ {0} كغ — تمرين اليوم مُصمَّم لحرق سعرات أكثر.",
