  "Your data stays on this phone and in your Google Drive. Changes are no longer saved to your Google account or to the Drive file.": "تبقى بياناتك على هذا الهاتف وفي Google Drive. لن تُحفظ التغييرات بعد الآن في حساب Google ولا في ملف Drive.",
  "Every change is written to your file a moment after you make it. Sign in with Google as well to also keep a copy through Android Backup.": "يُكتب كل تغيير في ملفك بعد لحظات من إجرائه. سجّل الدخول بحساب Google أيضًا للاحتفاظ بنسخة عبر النسخ الاحتياطي لأندرويد.",
