  "Lots of caffeine and sugar. Not for children, pregnancy or anyone sensitive to caffeine — one can a day at most.": "كثير من الكافيين والسكر. لا تناسب الأطفال ولا الحامل ولا من يتحسس من الكافيين — قوطية واحدة في اليوم كحد أقصى.",
  "Homemade sodas": "غازيات منزلية",
  "Made at home with soda water, fresh lemon and mint — you decide how sweet. Values assume a little sugar.": "تُحضَّر في البيت بالصودا والليمون الطازج والنعناع — وأنت تحدد الحلاوة. القيم على افتراض قليل من السكر.",
  "High in caffeine — not for children, pregnancy or anyone sensitive to caffeine. Never mix it with alcohol, and not during hard exercise in the heat.": "غني بالكافيين — لا يناسب الأطفال ولا الحامل ولا من يتحسس من الكافيين. لا تخلطه أبدًا مع الكحول، ولا تشربه أثناء تمرين شاق في الحر.",
  "No sugar: sweetened with sweeteners, so almost no calories.": "بلا سكر: محلّى بمحلّيات، لذا سعراته شبه معدومة.",
  "Contains quinine, which gives the bitter taste.": "يحتوي على الكينين الذي يعطيه الطعم المر.",
