  "Halva sandwich (halawa w khubz)": "حلاوة وخبز",
  "Grilled corn on the cob (arnoos)": "عرنوس مشوي",
  "Amba (mango pickle)": "عمبة",
  "Instant coffee 3-in-1 (sachet)": "قهوة سريعة 3 في 1 (ظرف)",
  "Your school week, your times": "أسبوع دوامك، بأوقاتك أنت",
  "Up at 7:00, water, breakfast, get ready, school 7:30–12:40 with nothing inside it, home, water, lunch and a drink — then a nap, homework, games, review, sport, dinner with water and a light snack before bed.": "استيقاظ 7:00، ماء، فطور، تجهّز، دوام 7:30–12:40 بلا أي شيء داخله، رجوع للبيت، ماء، غداء ومشروب — ثم قيلولة وواجبات وألعاب ومراجعة ورياضة وعشاء مع ماء وسناك خفيف قبل النوم.",
  "Friday and Saturday too": "والجمعة والسبت أيضًا",
  "Sleep in, an Iraqi breakfast, study, phone & games, helping at home, football, family and rest — every block with its calories.": "نوم متأخر، فطور عراقي، دراسة، موبايل وألعاب، مساعدة في البيت، كرة قدم، عائلة وراحة — وكل فترة مع سعراتها.",
  "Many more nuts, with Iraqi names": "مكسرات أكثر بكثير، بأسمائها العراقية",
  "Melon seeds, lemon pistachios, acorns, royal and seed kerzat, shamiya, termis — and dried fruits and dates: zbeeb, kishmish, zahdi, khastawi, barhi, figs, qamar al-din, mlabbas and more.": "حب بطيخ، فستق بالحامض، بلوط، كرزات ملوكي وكرزات حَب، شامية، ترمس — وفواكه مجففة وتمور: زبيب، كشمش، زهدي، خستاوي، برحي، تين، قمر الدين، ملبّس وغيرها.",
  "More Iraqi drinks": "مشروبات عراقية أكثر",
  "Chai haleeb, mint and lemon tea, kakao, milk with dibis, Turkish coffee, Nescafé, hamudh hilu and the juice shop: orange, carrot, apple, grape, mango, banana and strawberry milk and the Iraqi cocktail.": "شاي بالحليب، شاي بالنعناع وبالليمون، كاكاو، حليب بالدبس، قهوة تركية، نسكافيه، حامض حلو، ومحل العصير: برتقال وجزر وتفاح وعنب ومانجو وموز وفراولة بالحليب والكوكتيل العراقي.",
  "Everyday Iraqi food": "أكلات عراقية يومية",
  "Eggs with samoon, cheese and labneh sandwiches, timman with fasolia or bamia, sheikh mahshi, shifta, makarona, amba, arnoos — and foods can go straight into your schedule.": "بيض مع صمون، لفات جبن ولبنة، تمن مع فاصولياء أو بامية، شيخ محشي، شفتة، معكرونة، عمبة، عرنوس — ويمكن إضافة الأكلات مباشرة إلى جدولك.",
  "A real profile picture": "صورة شخصية حقيقية",
  "Your own photo from the phone, or one of hundreds of symbols — faces, sport, animals, nature, food, Iraq — on 24 colours.": "صورتك من الهاتف، أو رمز من مئات الرموز — وجوه ورياضة وحيوانات وطبيعة وأكل والعراق — على 24 لونًا.",
  "All your steps as a walk across Iraq, city by city — and the last five weeks at a glance.": "كل خطواتك كأنها رحلة مشي عبر العراق، مدينة بعد مدينة — وآخر خمسة أسابيع بنظرة واحدة.",
  "Water, any amount": "الماء، بأي كمية",
  "Add any amount up to a 1.5 L bottle, and see if you are ahead or behind right now.": "أضف أي كمية حتى قنينة 1.5 لتر، واعرف إن كنت متقدّمًا أو متأخرًا الآن.",
  "Iraq themes": "ثيمات العراق",
  "The Tigris, the Euphrates, Ishtar blue, Baghdad nights, Basra palms, Mosul marble, the marshes and more — 1,442 themes in all.": "دجلة والفرات وأزرق عشتار وليالي بغداد ونخيل البصرة ومرمر الموصل والأهوار وغيرها — 1442 ثيمًا بالمجموع.",
  "No more buzzing on every tap": "لا اهتزاز مع كل لمسة بعد الآن",
  "The light vibration when you tap or swipe is off — switch it back on in Settings if you liked it.": "الاهتزاز الخفيف عند اللمس أو السحب أصبح مطفأً — يمكنك تشغيله من الإعدادات إن كنت تحبه.",
